(x, y, t) => {
  const cx = 240, cy = 120;
  const wx = Math.sin(x*0.018+t*0.25)*18 + Math.cos(y*0.013-t*0.18)*12 + Math.sin((x+y)*0.008+t*0.4)*8;
  const wy = Math.cos(y*0.02-t*0.22)*16 + Math.sin(x*0.015+t*0.3)*11 + Math.cos((x-y)*0.009-t*0.35)*7;
  const sx = x+wx, sy = y+wy;
  const dist = Math.sqrt((sx-cx)**2+(sy-cy)**2), ang = Math.atan2(sy-cy, sx-cx);
  const src = [
    [180+Math.sin(t*0.5)*120, 70+Math.cos(t*0.35)*45, 0.09, 2.2, 1.0],
    [320+Math.cos(t*0.45)*110, 170+Math.sin(t*0.6)*55, 0.07, 1.8, 0.8],
    [240+Math.sin(t*0.28+2)*150, 120+Math.cos(t*0.42+1)*100, 0.055, 2.5, 1.2],
