    [380+Math.sin(t*0.38+4)*100, 50+Math.cos(t*0.8+2)*75, 0.065, 2.8, 1.1],
    [200+Math.cos(t*0.32+5)*130, 210+Math.sin(t*0.48)*85, 0.085, 2.0, 0.9],
    [60+Math.sin(t*0.6+3)*70, 100+Math.cos(t*0.5+1)*60, 0.13, 1.6, 0.6],
    [420+Math.cos(t*0.33+2)*80, 130+Math.sin(t*0.65+4)*70, 0.075, 2.3, 1.05]
  ];
  let aS=0, iS=0, fS=0;
  for (const [sX,sY,f,sp,w] of src) {
    const d = Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const wave = Math.sin(d*f-t*sp);
    const wave2 = Math.sin(d*f*1.618-t*sp*0.78+0.5);
    aS += wave*w;
    iS += Math.sin(d*f*0.618+t*sp*0.55+1.2)*w;
    fS += (wave*wave2)*w;
  }
  const act=aS/8, inh=iS/8, feed=fS/8;
  const bg1 = Math.sin(sx*0.035+sy*0.022+t*0.7);
  const bg2 = Math.sin(sx*0.028-sy*0.038+t*0.95);
  const bg3 = Math.sin((sx+sy)*0.015+t*1.8)*0.6;
  const bg4 = Math.sin((sx-sy)*0.018-t*1.5)*0.5;
  const spiral1 = Math.sin(dist*0.045-ang*3.5-t*1.3);
  const spiral2 = Math.sin(dist*0.035+ang*4.5-t*1.05);
  const spiral3 = Math.sin(dist*0.06-ang*2-t*2.2)*0.5;
  const voronoi = (() => {
    let md = 99;
    for (let i = 0; i < 7; i++) {
      const px = (Math.sin(i*2.399+t*0.15*(1+i*0.1))*0.4+0.5)*480;
      const py = (Math.cos(i*2.399+1.5+t*0.12*(1+i*0.08))*0.4+0.5)*240;
      const d = Math.sqrt((sx-px)**2+(sy-py)**2);
      if (d < md) md = d;
    }
    return md;
  })();
  const cellEdge = Math.tanh((voronoi-12)*0.5)*-1;
  const rd1 = act - inh*0.65 + bg1*0.2 + (spiral1+spiral2)*0.25;
  const rd2 = feed*2.0 + bg3 + bg4 + spiral3;
