    const u = Math.sin(sx*0.12)*Math.sin((sy+s)*0.12)+Math.sin((sx+sy+s)*0.08+t)*0.4;
    const d = Math.sin(sx*0.12)*Math.sin((sy-s)*0.12)+Math.sin((sx+sy-s)*0.08+t)*0.4;
    return (r+l+u+d-4*c)*0.25;
  })();
  const reaction = Math.tanh((rd1 + rd2*0.35 + laplacian*1.5 + cellEdge*0.6)*1.8);
