  const shimmer = 1.0+Math.sin(ang*5+t*2)*Math.sin(dist*0.03-t)*0.05;
  const bri = lum*edge*shimmer;
  return [
    Math.min(255, (pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*bri)|0,
    Math.min(255, (pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*bri)|0,
    Math.min(255, (pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*bri)|0
  ];
}
